3	export class PatchError extends Error {
4	  constructor(message, index) {
5	    super(message);
6	    this.index = index;
7	  }
8	}
9	Object.defineProperty(PatchError.prototype, 'name', {
10	  value: 'PatchError',
11	  writable: true,
12	  configurable: true,
13	});
